import './Menu.css';

const Menu = () => {
  return (
    <nav className="menu">
      <ul>
        <li><a href="#">Opción 1</a></li>
        <li><a href="#">Opción 2</a></li>
        <li><a href="#">Opción 3</a></li>
      </ul>
    </nav>
  );
};

export default Menu;
